-- Human translators the About page credits (display names only; the AI is named in the header above).
L[0] = {}

addon.translation = {
-- 8283f17a English: All trees (Icy Veins)
[1] = "Alle Talentbäume (Icy Veins)",
-- da4da042 English: Every talent tree from level 1 to 70. Curse, then Unstable Affliction,
--     Immolate, Corruption and Siphon Life as learned, Shadow Bolt or Incinerate; Nightfall and
--     Backlash procs first; Seed, Hellfire and Shadowfury for three or more enemies. Solo it drains
--     when hurt, Life Taps, wands, and uses Drain Soul or a finisher on a dying target. Reminders:
--     Fel Armor, Demon Armor or Demon Skin, your demon, sacrifice, Soul Link, Amplify Curse and
--     Soulshatter. Fears and other curses stay with you.
[2] = "Jeder Talentbaum von Stufe 1 bis 70. Fluch, dann Instabiles Gebrechen, Feuerbrand, Verderbnis und Lebensentzug, sobald erlernt, Schattenblitz oder Verbrennen; Procs von Einbruch der Nacht und Heimzahlen zuerst; Saat der Verderbnis, Höllenfeuer und Schattenfurie für drei oder mehr Gegner. Solo entzieht sie Leben, wenn Sie verletzt sind, nutzt Aderlass, den Zauberstab und Seelendieb oder einen Finisher auf ein sterbendes Ziel. Erinnerungen: Teufelsrüstung, Dämonenrüstung oder Dämonenhaut, Ihr Dämon, Opferung, Seelenverbindung, Fluch verstärken und Seele brechen. Furcht und andere Flüche bleiben Ihnen überlassen.",
-- e3790b25 English: Drain-tank (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Warlock,
--     The Burning Crusade Classic (variant key: DpsWowhead). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[3] = "Drain-Tanking (Wowhead)",
-- 522ed69f English: Warlock after Wowhead's guides, an alternative to the recommended Icy Veins
--     Warlock premade, off by default: enable it and disable that one, or raise its priority. Solo
--     it drain-tanks: Drain Life is the filler once your DoTs are up and Immolate and Siphon Life
--     are kept for elite mobs. In a group Immolate always goes on, after Corruption and Siphon
--     Life. Otherwise the same as the recommended premade.
[4] = "Hexenmeister nach den Leitfäden von Wowhead, eine Alternative zur empfohlenen integrierten Hexenmeister-Rotation nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Solo betreibt sie Drain-Tanking: Blutsauger ist der Füller, sobald Ihre DoTs wirken, und Feuerbrand und Lebensentzug werden für Elitegegner aufgespart. In einer Gruppe kommt Feuerbrand immer zum Einsatz, nach Verderbnis und Lebensentzug. Ansonsten wie die empfohlene integrierte Rotation.",
-- 7e8fd1de English: All trees
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Warlock,
--     WoW Forever (variant key: DPS).
[5] = "Alle Talentbäume",
-- 157e4fa1 English: Every Warlock talent tree from level 1 to 60, merged from Icy Veins, Wowhead
--     and Method; the steps for a tree appear once you know its talent spells. Pulls with Immolate
--     and Bane of Agony (Destruction precasts Shadow Bolt), uses Nightfall and Decimation procs,
--     keeps Demonic Brand up with Searing Pain. While moving it casts only instants. On packs:
--     Hellfire in a group, Rain of Fire, Corruption and Agony. Then Bane of Doom on elites and
--     bosses or Bane of Agony, Curse of the Elements in groups and on elites, Immolate, Corruption,
--     Siphon Life, Conflagrate and Shadowburn; solo it fills with Wrack, Drain Life (with a drain
--     talent) or the wand; otherwise Incinerate or Shadow Bolt. Reminders: armor, a demon
--     (Succubus, else Voidwalker, else Imp), Fel Domination, Demonic Sacrifice with Demonic Pact,
--     Soul Link, weapon stones, Amplify Curse and Bane of Havoc for a second enemy. Left to you:
--     sending the pet in, other curses, Fear, Healthstones and other targets. Health and mana are
--     hidden from addons on Forever, so the execute window (Drain Soul, Shadowburn as the killing
--     blow), Life Tap, Health Funnel and draining when hurt are your call.
[6] = "Jeder Hexenmeister-Talentbaum von Stufe 1 bis 60, zusammengeführt aus Icy Veins, Wowhead und Method; die Schritte eines Baums erscheinen, sobald Sie seine Talentzauber beherrschen. Zieht mit Feuerbrand und Omen der Pein (Zerstörung wirkt Schattenblitz vorab), nutzt Procs von Einbruch der Nacht und Dezimierung, hält Dämonisches Brandmal mit Sengendem Schmerz aufrecht. In Bewegung wirkt sie nur Spontanzauber. Gegen Gruppen: Höllenfeuer in einer Gruppe, Feuerregen, Verderbnis und Pein. Dann Omen der Verdammnis gegen Elitegegner und Bosse oder Omen der Pein, Fluch der Elemente in Gruppen und gegen Elitegegner, Feuerbrand, Verderbnis, Lebensentzug, Feuersbrunst und Schattenbrand; solo füllt sie mit Zermürben, Blutsauger (mit einem Entzugstalent) oder dem Zauberstab; sonst Verbrennen oder Schattenblitz. Erinnerungen: Rüstung, ein Dämon (Sukkubus, sonst Leerwandler, sonst Wichtel), Teufelsbeherrschung, Dämonische Opferung mit Dämonischem Pakt, Seelenverbindung, Waffensteine, Fluch verstärken und Omen der Verwüstung für einen zweiten Gegner. Ihnen überlassen: den Begleiter angreifen lassen, andere Flüche, Furcht, Gesundheitssteine und weitere Ziele. Gesundheit und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst über das Zeitfenster zum Erledigen (Seelendieb, Schattenbrand als Todesstoß), Aderlass, Lebenslinie und das Entziehen von Leben bei Verletzung.",
-- 8573424f English: Icy Veins' Warlock leveling: the wand is the solo filler, Voidwalker is the
--     default demon, Affliction and Destruction sacrifice their demon and play without one (from 41
--     and 55), Demonology keeps Demonic Brand up and uses Immolate only as a filler, and
--     Destruction puts Bane of Havoc on the durable enemy of a pack and Conflagrates on cooldown
--     once Incinerate is known. Choose it instead of the recommended Warlock premade if you follow
--     Icy Veins. Health, mana and time to die are hidden from addons on Forever, so Drain Life when
--     hurt, Life Tap and which targets will live long enough for DoTs are your call. An alternative
--     to the recommended Warlock DPS premade, off by default: enable it and disable that one, or
--     raise its priority.
[7] = "Hexenmeister-Leveling nach Icy Veins: Der Zauberstab ist der Solo-Füller, Leerwandler ist der Standarddämon, Gebrechen und Zerstörung opfern ihren Dämon und spielen ohne (ab 41 bzw. 55), Dämonologie hält Dämonisches Brandmal aufrecht und nutzt Feuerbrand nur als Füller, und Zerstörung setzt Omen der Verwüstung auf den widerstandsfähigsten Gegner einer Gruppe und Feuersbrunst bei Abklingzeit-Ende, sobald Verbrennen bekannt ist. Wählen Sie diese statt der empfohlenen integrierten Hexenmeisterrotation, wenn Sie Icy Veins folgen. Gesundheit, Mana und die Zeit bis zum Tod sind für Addons unter Forever verborgen, daher entscheiden Sie selbst, wann Sie Blutsauger bei Verletzung, Aderlass und DoTs auf Ziele einsetzen, die lange genug leben. Eine Alternative zur empfohlenen integrierten Hexenmeister-DPS-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität.",
-- b9f016be English: All trees (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Warlock,
--     WoW Forever (variant key: DPS / Wowhead). Names in parentheses (guide or tool such as Icy
--     Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern) are proper
--     names and stay unchanged.
[8] = "Alle Talentbäume (Wowhead)",
-- 02cc5c3e English: Wowhead's level-30 Warlock: Affliction and Demonology drain-tank with the
--     Succubus (Corruption and Agony, no Immolate, then Drain Life for the rest of the fight;
--     health and mana are hidden on Forever, so Life Tap is your call), Demonology keeps Demonic
--     Brand up and Agonies only big targets, Destruction puts Agony, Corruption and Immolate on
--     every mob, Conflagrates just before Immolate ends, saves Shadowburn for the killing blow and
--     wands with the Voidwalker. Amplify Curse on every cooldown; Curse of the Elements and Bane of
--     Doom only on elites and bosses; no pack section. Wowhead's guides stop at level 30. An
--     alternative to the recommended Warlock DPS premade, off by default: enable it and disable
--     that one, or raise its priority.
[9] = "Hexenmeister auf Stufe 30 nach Wowhead: Gebrechen und Dämonologie betreiben Drain-Tanking mit dem Sukkubus (Verderbnis und Pein, kein Feuerbrand, dann Blutsauger für den Rest des Kampfes; Gesundheit und Mana sind unter Forever verborgen, daher entscheiden Sie selbst über Aderlass), Dämonologie hält Dämonisches Brandmal aufrecht und setzt Pein nur auf große Ziele, Zerstörung setzt Pein, Verderbnis und Feuerbrand auf jeden Gegner, wirkt Feuersbrunst kurz bevor Feuerbrand endet, spart Schattenbrand für den Todesstoß auf und nutzt mit dem Leerwandler den Zauberstab. Fluch verstärken bei jedem Abklingzeit-Ende; Fluch der Elemente und Omen der Verdammnis nur gegen Elitegegner und Bosse; kein Abschnitt für Gruppen von Gegnern. Die Leitfäden von Wowhead enden bei Stufe 30. Eine Alternative zur empfohlenen integrierten Hexenmeister-DPS-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität.",
-- be7ca540 English: Recommended for Affliction in Midnight. In combat the game now hides your DoTs,
--     procs, cooldown times and health from addons, so this shows Blizzard's own Assisted Combat
--     suggestion (the one-button rotation, which keeps Agony and Corruption, spends shards on
--     Unstable Affliction and handles Grimoire of Sacrifice), and stops while you cast, channel or
--     have no enemy targeted. Reminders for what it leaves out: Summon Darkglare in combat, a
--     Felhunter between pulls unless you sacrificed your demon, Command Demon on an interruptible
--     cast (it lights only where the game lets the cast be read), Dark Pact and Unending Resolve
--     whenever they are ready in combat (health is hidden on Retail, so when to use them is your
--     call).
[10] = "Empfohlen für Gebrechen in Midnight. Im Kampf verbirgt das Spiel nun Ihre DoTs, Procs, Abklingzeiten und Gesundheit vor Addons, daher zeigt diese Rotation den eigenen Vorschlag von Blizzards Kampfassistent (die Ein-Tasten-Rotation, die Agonie und Verderbnis aufrechterhält, Seelensplitter für Instabiles Gebrechen ausgibt und Grimoire der Opferung übernimmt) und pausiert, während Sie wirken, kanalisieren oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Dunkelblick beschwören im Kampf, Teufelsjäger beschwören zwischen den Kämpfen, sofern Sie Ihren Dämon nicht geopfert haben, Dämon kommandieren bei einem unterbrechbaren Zauber (es leuchtet nur dort auf, wo das Spiel den Zauber auslesen lässt), Dunkler Pakt und Erbarmungslose Entschlossenheit, wann immer sie im Kampf bereit sind (die Gesundheit ist unter Retail verborgen, daher bleibt der Zeitpunkt Ihnen überlassen).",
-- d01f383a English: Reference only, off by default: the Icy Veins and SimulationCraft (Soul
--     Harvester) order reads DoT timers, Nightfall and Shard Instability, which Midnight hides in
--     combat. Haunt before the pull; Seed of Corruption on three or more engaged enemies without
--     your Corruption; Haunt; Agony and Corruption or Wither under 3 seconds; Dark Harvest at two
--     shards or fewer; Unstable Affliction at 5 shards; Malefic Grasp, else Shadow Bolt, on two
--     Nightfall; Unstable Affliction on Shard Instability or at 4 shards; Drain Soul; Shadow Bolt.
--     Reminders: Summon Darkglare once Dark Harvest is cooling, Malevolence, your Felhunter, and
--     the shared ones.
[11] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft (Seelenernter) liest DoT-Timer, Einbruch der Nacht und Splitterinstabilität, die Midnight im Kampf verbirgt. Heimsuchung vor dem Pull; Saat der Verderbnis gegen drei oder mehr Gegner im Kampf ohne Ihre Verderbnis; Heimsuchung; Agonie und Verderbnis oder Welken unter 3 Sekunden; Dunkle Ernte bei zwei Seelensplittern oder weniger; Instabiles Gebrechen bei 5 Seelensplittern; Bösartiger Griff, sonst Schattenblitz, bei zwei Stapeln Einbruch der Nacht; Instabiles Gebrechen bei Splitterinstabilität oder bei 4 Seelensplittern; Seelendieb; Schattenblitz. Erinnerungen: Dunkelblick beschwören, sobald Dunkle Ernte abklingt, Böswilligkeit, Teufelsjäger beschwören und die gemeinsamen.",
-- c6249f11 English: Recommended for Demonology in Midnight. Shows Blizzard's Assisted Combat
--     suggestion (Call Dreadstalkers, Hand of Gul'dan, Demonbolt, Power Siphon and Tyrant), and
--     stops while you cast, channel or have no enemy targeted. Reminders for what it leaves out:
--     Summon Demonic Tyrant while the Dreadstalkers you called in the last 12 seconds are out,
--     Grimoire: Imp Lord, Grimoire: Fel Ravager and Summon Doomguard in combat, a Felguard between
--     pulls, Command Demon, Dark Pact, Unending Resolve.
[12] = "Empfohlen für Dämonologie in Midnight. Zeigt den Vorschlag von Blizzards Kampfassistent (Schreckenspirscher rufen, Hand von Gul'dan, Dämonenblitz, Kraftentzug und Tyrann) und pausiert, während Sie wirken, kanalisieren oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Dämonischen Tyrannen beschwören, solange die in den letzten 12 Sekunden gerufenen Schreckenspirscher draußen sind, Grimoire: Wichtellord, Grimoire: Teufelsverheerer und Verdammniswache beschwören im Kampf, Teufelswache beschwören zwischen den Kämpfen, Dämon kommandieren, Dunkler Pakt, Erbarmungslose Entschlossenheit.",
-- 631224a9 English: Reference only, off by default: the Icy Veins and SimulationCraft (Diabolist)
--     order reads Demonic Core, imp counts and cooldown timers, which Midnight hides in combat.
--     Power Siphon, Demonbolt and Shadow Bolt before the pull; then Power Siphon at one Demonic
--     Core or none, Grimoire: Imp Lord, Grimoire: Fel Ravager, Summon Doomguard, Call
--     Dreadstalkers, Summon Demonic Tyrant at 5 shards, Implosion on three or more engaged enemies,
--     Ruination, Hand of Gul'dan at 3 shards or more, Infernal Bolt below 3, Demonbolt on Demonic
--     Core below 4, Shadow Bolt.
[13] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft (Diaboliker) liest Dämonischen Kern, Wichtelzahlen und Abklingzeit-Timer, die Midnight im Kampf verbirgt. Kraftentzug, Dämonenblitz und Schattenblitz vor dem Pull; dann Kraftentzug bei einem oder keinem Dämonischen Kern, Grimoire: Wichtellord, Grimoire: Teufelsverheerer, Verdammniswache beschwören, Schreckenspirscher rufen, Dämonischen Tyrannen beschwören bei 5 Seelensplittern, Implosion gegen drei oder mehr Gegner im Kampf, Verwüstung, Hand von Gul'dan bei 3 Seelensplittern oder mehr, Höllenblitz unter 3, Dämonenblitz bei Dämonischem Kern unter 4, Schattenblitz.",
-- e652e84a English: Recommended for Destruction in Midnight. Shows Blizzard's Assisted Combat
--     suggestion (Immolate or Wither, Conflagrate, Chaos Bolt, Rain of Fire, Soul Fire,
--     Malevolence), and stops while you cast, channel or have no enemy targeted. Reminders for what
--     it leaves out: Summon Infernal in combat, an Imp between pulls unless you sacrificed your
--     demon, Command Demon, Dark Pact, Unending Resolve. Havoc on a second target stays with you.
[14] = "Empfohlen für Zerstörung in Midnight. Zeigt den Vorschlag von Blizzards Kampfassistent (Feuerbrand oder Welken, Feuersbrunst, Chaosblitz, Feuerregen, Seelenfeuer, Böswilligkeit) und pausiert, während Sie wirken, kanalisieren oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Höllenbestie beschwören im Kampf, Wichtel beschwören zwischen den Kämpfen, sofern Sie Ihren Dämon nicht geopfert haben, Dämon kommandieren, Dunkler Pakt, Erbarmungslose Entschlossenheit. Verwüstung auf einem zweiten Ziel bleibt Ihnen überlassen.",
-- ad764c7b English: Reference only, off by default: SimulationCraft's order reads Immolate,
--     Backdraft, charges and cooldown timers, which Midnight hides in combat. Soul Fire and
--     Incinerate before the pull; on three or more engaged enemies Rain of Fire at 3 shards and
--     Cataclysm; then Soul Fire at 4 shards or fewer, Chaos Bolt only at 5, Conflagrate at two
--     charges or below 4 shards without Backdraft, Summon Infernal, Malevolence, Wither or Immolate
--     in its last 30%, Ruination, Cataclysm, Infernal Bolt at 3 shards or fewer, Incinerate.
[15] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von SimulationCraft liest Feuerbrand, Pyrolyse, Aufladungen und Abklingzeit-Timer, die Midnight im Kampf verbirgt. Seelenfeuer und Verbrennen vor dem Pull; gegen drei oder mehr Gegner im Kampf Feuerregen bei 3 Seelensplittern und Kataklysmus; dann Seelenfeuer bei 4 Seelensplittern oder weniger, Chaosblitz nur bei 5, Feuersbrunst bei zwei Aufladungen oder unter 4 Seelensplittern ohne Pyrolyse, Höllenbestie beschwören, Böswilligkeit, Welken oder Feuerbrand in seinen letzten 30 %, Verwüstung, Kataklysmus, Höllenblitz bei 3 Seelensplittern oder weniger, Verbrennen.",
-- e10ed7f7 English: Chaos Bolt before capping reference (Icy Veins)
[16] = "Chaosblitz vor dem Maximum, Referenz (Icy Veins)",
-- f093635c English: Reference only, off by default: Icy Veins' Hellcaller order, which spends
--     shards on Chaos Bolt before they cap and uses Shadowburn and Channel Demonfire on cooldown.
--     Rain of Fire on three or more engaged enemies; Wither or Immolate kept up; Summon Infernal;
--     Malevolence; Shadowburn; Soul Fire below 4 shards; Chaos Bolt at 4 or more; Cataclysm;
--     Infernal Bolt below 4; Channel Demonfire; Conflagrate; Incinerate.
[17] = "Nur als Referenz, standardmäßig deaktiviert: die Höllenrufer-Reihenfolge von Icy Veins, die Seelensplitter für Chaosblitz ausgibt, bevor sie das Maximum erreichen, und Schattenbrand und Dämonenfeuer kanalisieren bei Abklingzeit-Ende nutzt. Feuerregen gegen drei oder mehr Gegner im Kampf; Welken oder Feuerbrand aufrechterhalten; Höllenbestie beschwören; Böswilligkeit; Schattenbrand; Seelenfeuer unter 4 Seelensplittern; Chaosblitz bei 4 oder mehr; Kataklysmus; Höllenblitz unter 4; Dämonenfeuer kanalisieren; Feuersbrunst; Verbrennen.",
-- 9f1e219f English: Recommended before you choose a specialization (while the game reports the
--     Warlock's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests
--     next, the one rotation advice the game still lets an addon read in Midnight combat; it waits
--     while you cast or channel. Alongside it, the reminders every Warlock premade shares, each
--     once you know its spell. When you choose a specialization at level 10, that specialization's
--     premades take over.
[18] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Hexenmeisters meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Hexenmeister-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung.",
-- 2628a00c English: Every tree
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Warlock,
--     Classic Era (variant key: DPS).
[19] = "Alle Talentbäume",
-- cd5cc4e5 English: Levels 1–60, every talent tree, also on Hardcore and Self-Found realms; built
--     from Wowhead, Icy Veins, Warcraft Tavern and simulator. Stops while you cast or channel and
--     never tags a mob someone else is fighting while you are solo. Nightfall's Shadow Trance
--     first; Shadowburn and Searing Pain to finish a group target; a solo target about to die gets
--     Drain Soul (for a shard, or with Improved Drain Soul), Shadowburn or Conflagrate, then the
--     wand, never new DoTs. While moving only instants. On three or more enemies: Hellfire when
--     they are on you and you have half your health, otherwise Rain of Fire. One curse: in raids
--     Curse of Shadow or the Elements when nobody has it, Doom on long elite fights, otherwise
--     Agony. Immolate when it pays (Destruction, raids, or with 40% mana), Corruption, Siphon Life
--     (in raids only on Shadow Vulnerability). Solo: Dark Pact, Life Tap when healthy, Drain Life
--     when hurt, the wand. Shadow Bolt otherwise. Reminders: Demon Armor or Demon Skin, your pet
--     (Voidwalker solo, Imp in a group, Succubus for Demonic Sacrifice), Fel Domination, Demonic
--     Sacrifice, Amplify Curse, Voidwalker Sacrifice and a Healthstone when low, Health Funnel.
--     Curse assignments, Curse of Recklessness on a fleeing mob, Fear, Banish, Soulstones and
--     creating Healthstones stay with you.
[20] = "Stufen 1–60, jeder Talentbaum, auch auf Hardcore- und Self-Found-Realms; zusammengestellt aus Wowhead, Icy Veins, Warcraft Tavern und Simulation. Pausiert, während Sie wirken oder kanalisieren, und markiert solo nie einen Gegner, den jemand anderes bekämpft. Schattentrance von Einbruch der Nacht zuerst; Schattenbrand und Sengender Schmerz, um ein Ziel in der Gruppe zu erledigen; ein Solo-Ziel kurz vor dem Tod erhält Seelendieb (für einen Splitter oder mit Verbessertem Seelendieb), Schattenbrand oder Feuersbrunst, dann den Zauberstab, nie neue DoTs. In Bewegung nur Spontanzauber. Gegen drei oder mehr Gegner: Höllenfeuer, wenn sie Sie angreifen und Sie die Hälfte Ihrer Gesundheit haben, sonst Feuerregen. Ein Fluch: in Schlachtzügen Fluch der Schatten oder der Elemente, wenn niemand ihn wirkt, Fluch der Verdammnis bei langen Kämpfen gegen Elitegegner, sonst Fluch der Pein. Feuerbrand, wenn er sich lohnt (Zerstörung, Schlachtzüge oder ab 40 % Mana), Verderbnis, Lebensentzug (in Schlachtzügen nur bei Schattenverwundbarkeit). Solo: Dunkler Pakt, Aderlass bei guter Gesundheit, Blutsauger bei Verletzung, der Zauberstab. Sonst Schattenblitz. Erinnerungen: Dämonenrüstung oder Dämonenhaut, Ihr Begleiter (Leerwandler solo, Wichtel in einer Gruppe, Sukkubus für Dämonische Opferung), Teufelsbeherrschung, Dämonische Opferung, Fluch verstärken, Opferung des Leerwandlers und ein Gesundheitsstein bei niedriger Gesundheit, Lebenslinie. Fluchzuweisungen, Fluch der Tollkühnheit auf einen fliehenden Gegner, Furcht, Verbannen, Seelensteine und das Herstellen von Gesundheitssteinen bleiben Ihnen überlassen.",
-- 2a4e91fe English: Drain tank (Warcraft Tavern)
[21] = "Drain-Tanking (Warcraft Tavern)",
-- f3fb6b8f English: Warcraft Tavern's leveling style, an alternative to the recommended Warlock
--     premade, off by default: enable it and disable that one, or raise its priority. The Imp, then
--     the Succubus from level 20. Immolate, Siphon Life and Corruption, then solo Drain Life as the
--     filler once you learn its fourth rank (the wand before), Life Tap whenever your health is
--     nearly full and Dark Pact before your pet's mana is full. In raids every DoT the slots allow,
--     then Shadow Bolt. Same finishers, curse and safety reminders as the recommended premade;
--     fearing a second mob stays with you.
[22] = "Der Leveling-Stil von Warcraft Tavern, eine Alternative zur empfohlenen integrierten Hexenmeister-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Der Wichtel, ab Stufe 20 dann der Sukkubus. Feuerbrand, Lebensentzug und Verderbnis, dann solo Blutsauger als Füller, sobald Sie seinen vierten Rang erlernen (davor der Zauberstab), Aderlass, wann immer Ihre Gesundheit fast voll ist, und Dunkler Pakt, bevor das Mana Ihres Begleiters voll ist. In Schlachtzügen jeder DoT, den die Plätze erlauben, dann Schattenblitz. Dieselben Finisher, Fluch- und Sicherheitserinnerungen wie die empfohlene integrierte Rotation; einen zweiten Gegner in Furcht zu versetzen bleibt Ihnen überlassen.",
-- 57dda3e2 English: Curse and Corruption raids (Icy Veins)
[23] = "Fluch und Verderbnis im Schlachtzug (Icy Veins)",
-- 95411363 English: Icy Veins' list for realms with the 16-debuff limit, an alternative to the
--     recommended Warlock premade, off by default: enable it and disable that one, or raise its
--     priority. In raids only your curse and Corruption, then Shadow Bolt, with no Immolate and no
--     Siphon Life. Leveling and dungeons play as the recommended premade.
[24] = "Die Liste von Icy Veins für Realms mit dem Limit von 16 Schwächungszaubern, eine Alternative zur empfohlenen integrierten Hexenmeister-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. In Schlachtzügen nur Ihr Fluch und Verderbnis, dann Schattenblitz, ohne Feuerbrand und ohne Lebensentzug. Leveln und Dungeons spielen sich wie die empfohlene integrierte Rotation.",
-- 4f0bc39e English: Tank (SoD, Metamorphosis)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Warlock,
--     Season of Discovery (variant key: Tank). Names in parentheses (guide or tool such as Icy
--     Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern) are proper
--     names and stay unchanged.
[25] = "Tank, Metamorphose (SoD)",
-- 4026dce5 English: Season of Discovery tank, chosen once Metamorphosis is engraved; built from
--     simulator, Icy Veins, Wowhead and Warcraft Tavern. Shadow Cleave whenever Defender's Resolve
--     is missing or ending, a Soul Fire! proc, Incinerate to keep its fire buff; on three or more
--     enemies Shadow Cleave, Lake of Fire, Shadowflame and Hellfire. Then a curse (Agony, else
--     Recklessness when nobody has it), Shadowflame (Immolate before you engrave it), Master
--     Channeler Drain Life, Corruption, Siphon Life, Conflagrate for Backdraft, Soul Fire under
--     Decimation below 35%, and Searing Pain as the threat filler. Reminders: Metamorphosis, Fel
--     Armor, your pet, Immolation Aura, Demonic Grace, Vengeance when low, Menace when the target
--     attacks someone else, Demonic Howl on packs, Amplify Curse, Life Tap for a pet low on mana.
--     Infernal Armor stays with you.
[26] = "Tank in der Saison der Entdeckungen, gewählt, sobald Metamorphose graviert ist; zusammengestellt aus Simulation, Icy Veins, Wowhead und Warcraft Tavern. Schattenspalten, wann immer Entschluss des Verteidigers fehlt oder ausläuft, ein Proc von Seelenfeuer!, Verbrennen, um seinen Feuer-Stärkungszauber zu halten; gegen drei oder mehr Gegner Schattenspalten, See des Feuers, Schattenflamme und Höllenfeuer. Dann ein Fluch (Fluch der Pein, sonst Tollkühnheit, wenn niemand ihn wirkt), Schattenflamme (Feuerbrand, bevor Sie sie gravieren), Blutsauger mit Meisterkanalisierer, Verderbnis, Lebensentzug, Feuersbrunst für Pyrolyse, Seelenfeuer während Dezimierung unter 35 % und Sengender Schmerz als Bedrohungsfüller. Erinnerungen: Metamorphose, Teufelsrüstung, Ihr Begleiter, Feuerbrandaura, Dämonische Anmut, Rache bei niedriger Gesundheit, Plagegeist, wenn das Ziel jemand anderen angreift, Dämonisches Heulen gegen Gruppen, Fluch verstärken, Aderlass für einen Begleiter mit wenig Mana. Höllische Rüstung bleibt Ihnen überlassen.",
-- 8e9ea310 English: Season of Discovery Destruction, chosen once Chaos Bolt or Incinerate is
--     engraved; built from simulator Phase 6 and Wowhead. Shadowburn and Searing Pain to finish;
--     instants while moving; Incinerate's buff, Lake of Fire and Hellfire on packs; a curse
--     (Recklessness in a group when nobody has it, Doom on long elite fights, else Agony);
--     Conflagrate only to keep Backdraft; Immolate and Incinerate's buff kept up; below 35% Soul
--     Fire under Decimation instead of Chaos Bolt; Soul Fire! procs; Chaos Bolt; solo Master
--     Channeler Drain Life and Life Tap; Incinerate (Shadow Bolt before you engrave it). Reminders:
--     Fel Armor, the Imp, Amplify Curse and the safety reminders.
[27] = "Zerstörung in der Saison der Entdeckungen, gewählt, sobald Chaosblitz oder Verbrennen graviert ist; zusammengestellt aus Simulation Phase 6 und Wowhead. Schattenbrand und Sengender Schmerz zum Erledigen; Spontanzauber in Bewegung; der Stärkungszauber von Verbrennen, See des Feuers und Höllenfeuer gegen Gruppen; ein Fluch (Tollkühnheit in einer Gruppe, wenn niemand ihn wirkt, Fluch der Verdammnis bei langen Kämpfen gegen Elitegegner, sonst Fluch der Pein); Feuersbrunst nur, um Pyrolyse zu halten; Feuerbrand und der Stärkungszauber von Verbrennen aufrechterhalten; unter 35 % Seelenfeuer während Dezimierung statt Chaosblitz; Procs von Seelenfeuer!; Chaosblitz; solo Blutsauger mit Meisterkanalisierer und Aderlass; Verbrennen (Schattenblitz, bevor Sie es gravieren). Erinnerungen: Teufelsrüstung, der Wichtel, Fluch verstärken und die Sicherheitserinnerungen.",
-- c007c49e English: Fire, Conflagrate on cooldown (SoD, Icy Veins)
[28] = "Feuer, Feuersbrunst bei Abklingzeit-Ende (SoD, Icy Veins)",
-- 11cdbaf7 English: Icy Veins' and Warcraft Tavern's Season of Discovery Destruction, an
--     alternative to the recommended Season of Discovery Fire premade, off by default: enable it
--     and disable that one, or raise its priority. Immolate kept up, Conflagrate and Chaos Bolt on
--     cooldown (Chaos Bolt also below 35%), Incinerate's buff, Soul Fire under Decimation below
--     35%, Incinerate filler; the damage curse only while moving, with Recklessness in a group when
--     nobody has it.
[29] = "Zerstörung in der Saison der Entdeckungen nach Icy Veins und Warcraft Tavern, eine Alternative zur empfohlenen integrierten Feuerrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Feuerbrand aufrechterhalten, Feuersbrunst und Chaosblitz bei Abklingzeit-Ende (Chaosblitz auch unter 35 %), der Stärkungszauber von Verbrennen, Seelenfeuer während Dezimierung unter 35 %, Verbrennen als Füller; der Schadensfluch nur in Bewegung, mit Tollkühnheit in einer Gruppe, wenn niemand ihn wirkt.",
-- 998799fe English: Shadow, Affliction and Felguard (SoD)
[30] = "Schatten, Gebrechen und Teufelswache (SoD)",
-- c8da1636 English: Season of Discovery Affliction and Felguard builds, and every SoD Warlock no
--     other premade fits; built from simulator Phase 6, Wowhead and Icy Veins. Nightfall procs;
--     Shadowburn or Drain Soul to finish a group target; a dying solo target gets Drain Soul, not
--     DoTs; instants while moving; Lake of Fire and Hellfire on packs; a curse (Recklessness in a
--     group when nobody has it, else Agony); Unstable Affliction, Master Channeler Drain Life,
--     Shadowflame (Immolate before it), Corruption, Haunt, Siphon Life (each renewed under 6
--     seconds with Invocation engraved); Drain Soul below 20% with Soul Siphon engraved; solo
--     sustain and the wand; Shadow Bolt. Reminders: Fel Armor, your pet (a Felguard once engraved),
--     Life Tap for a pet low on mana, Amplify Curse and the safety reminders. Curse assignments and
--     Shadow Bolt Volley packs stay with you.
[31] = "Gebrechen- und Teufelswachen-Builds in der Saison der Entdeckungen und jeder Hexenmeister der Saison der Entdeckungen, zu dem keine andere integrierte Rotation passt; zusammengestellt aus Simulation Phase 6, Wowhead und Icy Veins. Procs von Einbruch der Nacht; Schattenbrand oder Seelendieb, um ein Ziel in der Gruppe zu erledigen; ein sterbendes Solo-Ziel erhält Seelendieb, keine DoTs; Spontanzauber in Bewegung; See des Feuers und Höllenfeuer gegen Gruppen; ein Fluch (Tollkühnheit in einer Gruppe, wenn niemand ihn wirkt, sonst Fluch der Pein); Instabiles Gebrechen, Blutsauger mit Meisterkanalisierer, Schattenflamme (davor Feuerbrand), Verderbnis, Heimsuchung, Lebensentzug (jeweils unter 6 Sekunden erneuert, wenn Herbeirufung graviert ist); Seelendieb unter 20 %, wenn Seelenentzug graviert ist; Durchhalten im Solospiel und der Zauberstab; Schattenblitz. Erinnerungen: Teufelsrüstung, Ihr Begleiter (eine Teufelswache, sobald graviert), Aderlass für einen Begleiter mit wenig Mana, Fluch verstärken und die Sicherheitserinnerungen. Fluchzuweisungen und Schattenblitzsalve gegen Gruppen bleiben Ihnen überlassen.",
-- 9fe0ee40 English: Shadow, Drain Soul filler (SoD, simulator)
[32] = "Schatten, Seelendieb als Füller (SoD, Simulation)",
-- 8e9b4067 English: The simulator Phase 6 Affliction list for a Soul Siphon build, an alternative
--     to the recommended Season of Discovery Shadow premade, off by default: enable it and disable
--     that one, or raise its priority. Drain Soul is the filler at any health, and the next step
--     shows as soon as it is due so you can clip the channel for it; any other channel is left to
--     finish. Unstable Affliction and Shadowflame renewed with 7.5 seconds left, Agony and
--     Corruption with 6, Master Channeler Drain Life, Haunt, Shadow Bolt only on a Shadow Trance
--     proc, Siphon Life, Life Tap below 10% mana. Same reminders as the recommended premade.
[33] = "Die Gebrechen-Liste von Simulation für Phase 6 für einen Seelenentzug-Build, eine Alternative zur empfohlenen integrierten Schattenrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Seelendieb ist bei jeder Gesundheit der Füller, und der nächste Schritt erscheint, sobald er fällig ist, damit Sie die Kanalisierung dafür abbrechen können; jede andere Kanalisierung wird zu Ende geführt. Instabiles Gebrechen und Schattenflamme bei 7,5 verbleibenden Sekunden erneuert, Fluch der Pein und Verderbnis bei 6, Blutsauger mit Meisterkanalisierer, Heimsuchung, Schattenblitz nur bei einem Proc von Schattentrance, Lebensentzug, Aderlass unter 10 % Mana. Dieselben Erinnerungen wie die empfohlene integrierte Rotation.",
-- e15e8094 English: Recommended for Affliction from level 10 to 90 (chosen in the Affliction
--     specialization). Pre-casts Haunt or Unstable Affliction, opens a fresh elite with Soulburn
--     and Soul Swap, keeps Agony, Corruption and Unstable Affliction up (refreshing them early
--     while Dark Soul: Misery is up), casts Haunt whenever it runs low and you have two shards (or
--     in Dark Soul), channels Drain Soul for a shard when Haunt is ending and you have none, Drain
--     Soul below 20%, otherwise Malefic Grasp (Shadow Bolt before 42). Seed of Corruption on three
--     or more enemies (with Soulburn on six). Moving: instants and Fel Flame. Reminders: your pet,
--     Dark Intent, Curse of the Elements in a group, Dark Soul, Doomguard or Infernal, Grimoire of
--     Service or Sacrifice, Life Tap, defensives. Left to you: spreading DoTs to other targets and
--     Soul Swap moves between them.
[34] = "Empfohlen für Gebrechen von Stufe 10 bis 90 (gewählt in der Spezialisierung Gebrechen). Wirkt Heimsuchung oder Instabiles Gebrechen vor, eröffnet einen frischen Elitegegner mit Seelenbrand und Seelentausch, hält Agonie, Verderbnis und Instabiles Gebrechen aufrecht (erneuert sie früh, solange Finstere Seele: Elend aktiv ist), wirkt Heimsuchung, wann immer sie zur Neige geht und Sie zwei Splitter haben (oder während Finsterer Seele), kanalisiert Seelendieb für einen Splitter, wenn Heimsuchung ausläuft und Sie keinen haben, Seelendieb unter 20 %, sonst Bösartiger Griff (Schattenblitz vor Stufe 42). Saat der Verderbnis gegen drei oder mehr Gegner (mit Seelenbrand ab sechs). In Bewegung: Spontanzauber und Teufelsflamme. Erinnerungen: Ihr Begleiter, Finstere Absichten, Fluch der Elemente in einer Gruppe, Finstere Seele, Verdammniswache oder Höllenbestie, Grimoire der Dienstbarkeit oder der Opferung, Aderlass, Defensivfähigkeiten. Ihnen überlassen: das Verteilen von DoTs auf andere Ziele und Seelentausch-Übertragungen zwischen ihnen.",
-- e62d2301 English: Pool Haunt (Warcraft Tavern)
[35] = "Heimsuchung aufsparen (Warcraft Tavern)",
-- fd7bdbbd English: Off by default. Warcraft Tavern's and Method's shard policy: the same DoT
--     upkeep as the recommended Affliction premade, but Haunt is saved for four shards or Dark
--     Soul: Misery, and below 20% Soulburn and Soul Swap refresh every DoT whenever you have a
--     shard. Enable it and disable the recommended Affliction premade to use it.
[36] = "Standardmäßig deaktiviert. Die Splitter-Strategie von Warcraft Tavern und Method: dieselbe DoT-Pflege wie die empfohlene integrierte Gebrechen-Rotation, aber Heimsuchung wird für vier Splitter oder Finstere Seele: Elend aufgespart, und unter 20 % erneuern Seelenbrand und Seelentausch jeden DoT, wann immer Sie einen Splitter haben. Aktivieren Sie sie und deaktivieren Sie die empfohlene integrierte Gebrechen-Rotation, um sie zu verwenden.",
-- daf1315b English: Recommended for Demonology from level 10 to 90 (chosen in the Demonology
--     specialization). In caster form: Corruption, Hand of Gul'dan by charges, a second Hand of
--     Gul'dan into Metamorphosis when a one-stack Shadowflame is about to drop, Metamorphosis with
--     Dark Soul: Knowledge (or near full fury), Soul Fire at two Molten Core stacks or below 25%,
--     Hellfire on four or more enemies, Shadow Bolt. In Metamorphosis: Doom, Touch of Chaos to keep
--     Corruption up, Soul Fire on Molten Core, Immolation Aura or Void Ray on packs, Touch of
--     Chaos, and a cue to leave it when Dark Soul is down and fury is at 300 or less. Reminders:
--     Felguard (or Wrathguard), Dark Intent, Dark Soul, Imp Swarm, Grimoire: Felguard, Doomguard or
--     Infernal, Life Tap, Health Funnel solo. Left to you: Felstorm (pet autocast) and Demonic
--     Leap.
[37] = "Empfohlen für Dämonologie von Stufe 10 bis 90 (gewählt in der Spezialisierung Dämonologie). In Zauberergestalt: Verderbnis, Hand von Gul'dan nach Aufladungen, eine zweite Hand von Gul'dan als Übergang in Metamorphose, wenn eine Schattenflamme mit einem Stapel bald ausläuft, Metamorphose mit Finstere Seele: Wissen (oder bei fast vollem Dämonischem Furor), Seelenfeuer bei zwei Stapeln Geschmolzener Kern oder unter 25 %, Höllenfeuer gegen vier oder mehr Gegner, Schattenblitz. In Metamorphose: Verdammnis, Berührung des Chaos, um Verderbnis aufrechtzuerhalten, Seelenfeuer bei Geschmolzener Kern, Feuerbrandaura oder Leerenstrahl gegen Gruppen, Berührung des Chaos und ein Hinweis, sie zu verlassen, wenn Finstere Seele nicht aktiv ist und der Dämonische Furor bei 300 oder weniger liegt. Erinnerungen: Teufelswache (oder Zornwächter), Finstere Absichten, Finstere Seele, Wichtelschwarm, Grimoire: Teufelswache, Verdammniswache oder Höllenbestie, Aderlass, Lebenslinie solo. Ihnen überlassen: Teufelssturm (automatisches Wirken des Begleiters) und Dämonischer Sprung.",
-- 977579d3 English: Pool Molten Core (guides)
[38] = "Geschmolzener Kern aufsparen (Leitfäden)",
-- 96ffba45 English: Off by default. The guide consensus (Method, wowtbc.gg, Warcraft Tavern,
--     Wowhead): the recommended Demonology premade, except that in caster form Metamorphosis waits
--     for 900 fury or Dark Soul and Soul Fire is only cast at eight Molten Core stacks or below
--     25%, so the stacks are spent in demon form. Enable it and disable the recommended Demonology
--     premade to use it.
[39] = "Standardmäßig deaktiviert. Der Konsens der Leitfäden (Method, wowtbc.gg, Warcraft Tavern, Wowhead): die empfohlene integrierte Dämonologie-Rotation, außer dass in Zauberergestalt Metamorphose auf 900 Dämonischen Furor oder Finstere Seele wartet und Seelenfeuer nur bei acht Stapeln Geschmolzener Kern oder unter 25 % gewirkt wird, damit die Stapel in Dämonengestalt verbraucht werden. Aktivieren Sie sie und deaktivieren Sie die empfohlene integrierte Dämonologie-Rotation, um sie zu verwenden.",
-- b2f67ea8 English: For Destruction from level 10 to 90 (chosen in the Destruction specialization).
--     Pre-casts Incinerate, keeps Immolate up, never sits on two Conflagrate charges, spends embers
--     on Chaos Bolt (Shadowburn below 20%) at 3.5 embers or in Dark Soul: Instability, uses
--     Backdraft on Incinerate, and fills with Incinerate; a dying target gets Shadowburn. On three
--     or more enemies: Rain of Fire and Fire and Brimstone on four, then Immolate, Conflagrate and
--     Incinerate, and a cue to switch Fire and Brimstone off when your embers run out. Moving:
--     Shadowburn, Conflagrate, Fel Flame. Reminders: your pet or Grimoire of Sacrifice, Flames of
--     Xoroth, Dark Intent, Dark Soul, Havoc on two or more enemies (cast it on the second target
--     yourself), Doomguard or Infernal, Ember Tap and defensives.
[40] = "Für Zerstörung von Stufe 10 bis 90 (gewählt in der Spezialisierung Zerstörung). Wirkt Verbrennen vor, hält Feuerbrand aufrecht, lässt nie zwei Aufladungen von Feuersbrunst liegen, gibt Instabile Funken für Chaosblitz (Schattenbrand unter 20 %) bei 3,5 Funken oder während Finstere Seele: Instabilität aus, nutzt Pyrolyse für Verbrennen und füllt mit Verbrennen; ein sterbendes Ziel erhält Schattenbrand. Gegen drei oder mehr Gegner: Feuerregen und ab vier Feuer und Schwefel, dann Feuerbrand, Feuersbrunst und Verbrennen, und ein Hinweis, Feuer und Schwefel auszuschalten, wenn Ihre Funken aufgebraucht sind. In Bewegung: Schattenbrand, Feuersbrunst, Teufelsflamme. Erinnerungen: Ihr Begleiter oder Grimoire der Opferung, Flammen von Xoroth, Finstere Absichten, Finstere Seele, Verwüstung gegen zwei oder mehr Gegner (wirken Sie es selbst auf das zweite Ziel), Verdammniswache oder Höllenbestie, Funkenwandlung und Defensivfähigkeiten.",
-- a4d9e0da English: For a Warlock without a specialization (levels 1 to 9, or later before you
--     choose one). Corruption to pull and kept up, Drain Life below half health, Shadow Bolt.
--     Reminders: the Voidwalker when solo (the Imp in a group), and a Healthstone between pulls.
[41] = "Für einen Hexenmeister ohne Spezialisierung (Stufe 1 bis 9 oder später, bevor Sie eine wählen). Verderbnis zum Ziehen und aufrechterhalten, Blutsauger unter halber Gesundheit, Schattenblitz. Erinnerungen: der Leerwandler solo (der Wichtel in einer Gruppe) und ein Gesundheitsstein zwischen den Pulls.",
}
